import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.Dhf_H6O0.js";const m=JSON.parse('{"title":"Server Types Explained","description":"","frontmatter":{},"headers":[],"relativePath":"using-the-app/server-types.md","filePath":"using-the-app/server-types.md"}'),a={name:"using-the-app/server-types.md"};function n(i,e,l,p,h,d){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="server-types-explained" tabindex="-1">Server Types Explained <a class="header-anchor" href="#server-types-explained" aria-label="Permalink to &quot;Server Types Explained&quot;">​</a></h1><p>MCPBehindIT supports three MCP transport types. Each one describes how the gateway communicates with the MCP server.</p><h2 id="stdio-—-local-programs" tabindex="-1">stdio — Local programs <a class="header-anchor" href="#stdio-—-local-programs" aria-label="Permalink to &quot;stdio — Local programs&quot;">​</a></h2><p><strong>What it is:</strong> The gateway runs a program (like a Node.js script or Python tool) directly inside the Docker container. Communication happens through the program&#39;s standard input and output.</p><p><strong>Best for:</strong></p><ul><li>Open-source MCP servers from npm or pip</li><li>Custom tools you&#39;ve written</li><li>Anything that ships as a command-line program</li></ul><p><strong>Example:</strong> The official MCP memory server:</p><ul><li>Command: <code>npx</code></li><li>Arguments: <code>-y</code> and <code>@modelcontextprotocol/server-memory</code></li></ul><p><strong>How it works:</strong> The gateway starts the command inside the container, feeds it MCP requests via stdin, and reads responses from stdout.</p><div class="info custom-block"><p class="custom-block-title">Docker socket</p><p>Some catalog entries use <code>docker run</code> to start a separate container for the server. MCPBehindIT automatically mounts the Docker socket into the gateway container when needed.</p></div><h2 id="sse-—-remote-server-server-sent-events" tabindex="-1">SSE — Remote server (Server-Sent Events) <a class="header-anchor" href="#sse-—-remote-server-server-sent-events" aria-label="Permalink to &quot;SSE — Remote server (Server-Sent Events)&quot;">​</a></h2><p><strong>What it is:</strong> The gateway connects to a remote HTTP server that uses <strong>Server-Sent Events</strong> for streaming responses.</p><p><strong>Best for:</strong></p><ul><li>Remote MCP servers hosted by a third party</li><li>Servers that use the older SSE-based MCP transport</li></ul><p><strong>Example:</strong></p><ul><li>URL: <code>https://my-mcp-server.example.com/sse</code></li></ul><p><strong>How it works:</strong> The gateway opens an HTTP connection to the URL and listens for SSE events. Requests are sent as HTTP POST, responses stream back as events.</p><h2 id="streamable-http-—-remote-server-http-streaming" tabindex="-1">streamable-http — Remote server (HTTP streaming) <a class="header-anchor" href="#streamable-http-—-remote-server-http-streaming" aria-label="Permalink to &quot;streamable-http — Remote server (HTTP streaming)&quot;">​</a></h2><p><strong>What it is:</strong> The gateway connects to a remote HTTP server using the newer <strong>streamable HTTP</strong> transport. This is the recommended transport for remote servers and supports <strong>OAuth authentication</strong>.</p><p><strong>Best for:</strong></p><ul><li>Modern MCP servers that support the latest transport spec</li><li>Servers that require OAuth (like Telecontext)</li></ul><p><strong>Example:</strong> Telekom Telecontext:</p><ul><li>URL: <code>https://telecontext.trap.ng.telekom.net/mcp?toolCategories=knowledge,psa&amp;tools=...</code></li><li>OAuth: Configured automatically when added from the Catalog</li></ul><p><strong>How it works:</strong> Communication uses standard HTTP requests and responses with streaming support. When OAuth is configured, the gateway handles the entire authentication flow — you just sign in through your browser when prompted.</p><h2 id="which-type-should-i-choose" tabindex="-1">Which type should I choose? <a class="header-anchor" href="#which-type-should-i-choose" aria-label="Permalink to &quot;Which type should I choose?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Transport</th></tr></thead><tbody><tr><td>Installing an npm/pip MCP package</td><td><strong>stdio</strong></td></tr><tr><td>Connecting to a remote server without auth</td><td><strong>SSE</strong> or <strong>streamable-http</strong></td></tr><tr><td>Connecting to a remote server with OAuth</td><td><strong>streamable-http</strong></td></tr><tr><td>Using Telecontext</td><td><strong>streamable-http</strong> (set up automatically via Catalog)</td></tr><tr><td>Using Local RAG</td><td><strong>stdio</strong> (set up automatically via Catalog)</td></tr><tr><td>Not sure</td><td>Use the <strong>Catalog</strong> — it picks the right type for you</td></tr></tbody></table>',26)])])}const g=t(a,[["render",n]]);export{m as __pageData,g as default};
